/**
 * What ArgoCD may prune in the sightline namespace.
 *
 * ArgoCD tracks, and so prunes, what carries `app.kubernetes.io/instance`. The
 * Postgres claim, data-postgres-0, is generated by the StatefulSet and inherits
 * its labels; it is safe from a pruning sync only because none of them is the
 * tracking label. Its volume is local-path, reclaim=Delete: a pruned claim is
 * the data gone. So the label must never be injected, and the two objects whose
 * loss is the data's carry the annotation that forbids pruning them.
 */

import { readdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

const root = fileURLToPath(new URL("../deploy/k8s/", import.meta.url));
const files = ["base", "prod", "staging"].flatMap((dir) =>
  readdirSync(root + dir)
    .filter((f) => f.endsWith(".yaml"))
    .map((f) => `${dir}/${f}`),
);
const read = (f: string) => readFileSync(root + f, "utf8");

describe("ArgoCD tracking", () => {
  it("is never injected or written into a manifest", () => {
    expect(files.length).toBeGreaterThan(5);
    const tracked = files.filter((f) => read(f).includes("app.kubernetes.io/instance"));
    expect(tracked, "Postgres's generated claim would inherit it and become prunable").toEqual([]);
  });

  it.each([
    ["base/backup.yaml", "kind: PersistentVolumeClaim"],
    ["base/datastores.yaml", "kind: StatefulSet"],
  ])("%s: its %s is kept out of prune and delete", (file, kind) => {
    const text = read(file);
    const at = text.indexOf(kind);
    expect(at).toBeGreaterThan(-1);
    const metadata = text.slice(at, text.indexOf("\nspec:", at));
    expect(metadata).toContain('argocd.argoproj.io/sync-options: "Prune=false,Delete=false"');
  });
});
